module TopModule (
    input  clk,
    input  L,
    input  q_in,
    input  r_in,
    output Q
);

    // Internal signal to hold the 3-bit state (q[2:0])
    reg [2:0] q_reg;

    // Sequential logic: D flip-flop behavior with load and shift
    always @(posedge clk) begin
        if (L) begin
            // Load mode: shift in r_in as the new MSB (q[2])
            q_reg <= {r_in, q_reg[1:0]};
        end else begin
            // Shift mode: shift right, XOR feedback from q[2] into q[0]
            // New q[0] = q[1] XOR q[2]
            // New q[1] = q[0] (old)
            // New q[2] = q[2] (old, retained through the shift)
            q_reg <= {q_reg[1] ^ q_reg[2], q_reg[0], q_reg[2]};
        end
    end

    // Output assignment: map the MSB of the internal register to Q
    assign Q = q_reg[2];

endmodule

Prob096_review2015_fsmseq.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4'b0001 = S0, 4'b0010 = S1, 4'b0100 = S2, 4'b1000 = S3
    reg [3:0] state, next_state;

    // State register (synchronous reset, active-high)
    always @(posedge clk) begin
        if (reset)
            state <= 4'b0001;  // S0
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine for sequence detector)
    always @(*) begin
        case (state)
            4'b0001: begin // State S0
                if (data)
                    next_state = 4'b0010; // S0 --data=1--> S1
                else
                    next_state = 4'b0001; // S0 --data=0--> S0
            end
            4'b0010: begin // State S1
                if (data)
                    next_state = 4'b0100; // S1 --data=1--> S2
                else
                    next_state = 4'b0001; // S1 --data=0--> S0
            end
            4'b0100: begin // State S2
                if (data)
                    next_state = 4'b1000; // S2 --data=1--> S3
                else
                    next_state = 4'b0010; // S2 --data=0--> S1
            end
            4'b1000: begin // State S3
                if (data)
                    next_state = 4'b0010; // S3 --data=1--> S1 (overlap: last '1')
                else
                    next_state = 4'b0001; // S3 --data=0--> S0
            end
            default: next_state = 4'b0001;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    // start_shifting is 1 when in S3 (sequence 1101 found)
    assign start_shifting = (state == 4'b1000) ? 1'b1 : 1'b0;

endmodule

