module TopModule (
    input  clk,
    input  reset,
    input  x,
    output z
);

    // State encoding: 3 bits for five states (000..100)
    reg [2:0] state, next_state;

    // State register (synchronous reset, active-high)
    always @(posedge clk) begin
        if (reset)
            state <= 3'b000;  // state 000
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            3'b000: begin // state 000
                if (x == 1'b0)
                    next_state = 3'b000; // 000 -> 000
                else
                    next_state = 3'b001; // 000 -> 001
            end
            3'b001: begin // state 001
                if (x == 1'b0)
                    next_state = 3'b001; // 001 -> 001
                else
                    next_state = 3'b100; // 001 -> 100
            end
            3'b010: begin // state 010
                if (x == 1'b0)
                    next_state = 3'b010; // 010 -> 010
                else
                    next_state = 3'b001; // 010 -> 001
            end
            3'b011: begin // state 011
                if (x == 1'b0)
                    next_state = 3'b001; // 011 -> 001
                else
                    next_state = 3'b010; // 011 -> 010
            end
            3'b100: begin // state 100
                if (x == 1'b0)
                    next_state = 3'b011; // 100 -> 011
                else
                    next_state = 3'b100; // 100 -> 100
            end
            default: next_state = 3'b000;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    // z = 1 for states 011 and 100, else 0
    assign z = (state == 3'b011) | (state == 3'b100);

endmodule

Prob074_ece241_2014_q4.code:
module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal flip-flop outputs
    reg q_xor;
    reg q_and;
    reg q_or;

    // D flip-flop for XOR gate: second input is its own output
    always @(posedge clk) begin
        q_xor <= x ^ q_xor;
    end

    // D flip-flop for AND gate: second input is complemented output
    always @(posedge clk) begin
        q_and <= x & ~q_and;
    end

    // D flip-flop for OR gate: second input is complemented output
    always @(posedge clk) begin
        q_or <= x | ~q_or;
    end

    // Three-input NOR gate: output is Z
    assign z = ~(q_xor | q_and | q_or);

endmodule

