module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register
    reg [1:0] state; // 00: low, 01: middle, 10: high

    // Combinational logic for outputs
    // fr0 is always asserted when any sensor is active or state indicates need
    assign fr0 = (state != 2'b10) & (|s | (state == 2'b01));

    // fr1 asserted when between s1 and s0 (state 01) or below (state 00)
    assign fr1 = (state == 2'b01) | (state == 2'b00);

    // fr2 asserted only when below lowest sensor (state 00)
    assign fr2 = (state == 2'b00);

    // dfr (Supplemental flow valve) asserted when previous level was lower than current
    // This is true when we transition from low(00) to middle(01) or high(10)
    assign dfr = (state == 2'b01) | (state == 2'b10);

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: equivalent to long-time low level
            // No sensors asserted, all four outputs asserted
            state <= 2'b00;
        end else begin
            // Determine new state based on current sensors
            // Priority: Above s[2] > Between s[2]&s[1] > Between s[1]&s[0] > Below s[0]
            if (s[2]) begin
                // Water level above highest sensor
                state <= 2'b10;
            end else if (s[1]) begin
                // Between s[2] and s[1]
                state <= 2'b01;
            end else if (s[0]) begin
                // Between s[1] and s[0] or below s[0] depending on context
                // Here we treat s[0] alone as between s[1] and s[0]
                state <= 2'b01;
            end else begin
                // Below lowest sensor
                state <= 2'b00;
            end
        end
    end

endmodule

Prob154_fsm_ps2data.code:
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // load first byte into MSBs
                        done       <= 1'b0;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // shift in second byte
                    done       <= 1'b0;
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};  // shift in third byte
                    done       <= 1'b0;
                end

                BYTE3: begin
                    // Third byte received: assert done and output message
                    next_state <= IDLE;
                    out_bytes  <= shift_reg;
                    done       <= 1'b1;
                end

                default: next_state <= IDLE;
            endcase
        end
    end

endmodule

