module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 2'b00 = A, 2'b01 = B, 2'b10 = C, 2'b11 = D
    reg [1:0] state, next_state;

    // State register (synchronous reset, active low)
    always @(posedge clk) begin
        if (!resetn)
            state <= 2'b00;  // State A
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            2'b00: begin // State A
                // After reset de-assertion, set f=1 for one cycle, go to B
                next_state = 2'b01;
            end
            2'b01: begin // State B
                // Monitor x for sequence 1,0,1
                if (x)
                    next_state = 2'b10; // x=1 -> go to C
                else
                    next_state = 2'b01; // x=0 -> stay in B (waiting for next x)
            end
            2'b10: begin // State C
                // Monitor x=0 after previous x=1
                if (!x)
                    next_state = 2'b11; // x=0 -> go to D
                else
                    next_state = 2'b10; // x=1 -> stay in C
            end
            2'b11: begin // State D
                // Sequence 1,0,1 detected, now monitor y
                if (y)
                    next_state = 2'b11; // y=1 -> stay in D (g stays 1)
                else
                    next_state = 2'b00; // y=0 within 2 cycles -> go to A, g=0
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic (Moore machine)
    // f is 1 for one cycle after reset de-assertion (state A -> B transition)
    // We detect the transition from A (2'b00) to B (2'b01)
    assign f = (state == 2'b01) & (next_state == 2'b01) ? 1'b1 : 1'b0;

    // g is 1 when in state D (sequence detected and y=1 within 2 cycles)
    // g goes to 0 if y does not become 1 within two clock cycles (goes to state A)
    assign g = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

Prob155_lemmings4.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // States
    typedef enum logic [2:0] {
        WALK_LEFT,    // 000
        WALK_RIGHT,   // 001
        FALLING,      // 010
        DIGGING,      // 011
        SPLATTERED    // 100
    } state_t;

    state_t state, next_state;

    // Fall counter
    logic [4:0] fall_count, next_fall_count;

    // Walking direction register (0 = left, 1 = right)
    logic walk_dir, next_walk_dir;

    // Outputs
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_count <= 0;
            walk_dir <= 0;
        end else begin
            state <= next_state;
            fall_count <= next_fall_count;
            walk_dir <= next_walk_dir;
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state;
        next_fall_count = fall_count;
        next_walk_dir = walk_dir;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall when ground disappears
                    next_state = FALLING;
                    next_fall_count = 1;
                    next_walk_dir = 0; // walking left before fall
                end else if (dig) begin
                    // Start digging
                    next_state = DIGGING;
                    // walk_dir stays the same (already walking left)
                end else if (bump_left || bump_right) begin
                    // Switch direction
                    if (bump_left && !bump_right)
                        next_state = WALK_RIGHT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_LEFT;
                    else
                        next_state = WALK_RIGHT; // bumped both sides, switch to right
                    // Update walk_dir
                    next_walk_dir = (next_state == WALK_RIGHT) ? 1 : 0;
                end
                // else stay WALK_LEFT, walk_dir stays the same
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    next_fall_count = 1;
                    next_walk_dir = 1; // walking right before fall
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    if (bump_left && !bump_right)
                        next_state = WALK_LEFT;
                    else if (bump_right && !bump_left)
                        next_state = WALK_RIGHT;
                    else
                        next_state = WALK_LEFT; // bumped both sides, switch to left
                    next_walk_dir = (next_state == WALK_RIGHT) ? 1 : 0;
                end
            end

            FALLING: begin
                if (ground) begin
                    if (fall_count > 20) begin
                        // Splatter - fell for more than 20 cycles
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in same direction as before fall
                        if (walk_dir == 0) begin
                            next_state = WALK_LEFT;
                        end else begin
                            next_state = WALK_RIGHT;
                        end
                    end
                end else begin
                    // Still falling, increment counter
                    // Being bumped while falling has no effect
                    if (fall_count < 31)
                        next_fall_count = fall_count + 1;
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side, start falling
                    // Preserve the walking direction before digging
                    next_state = FALLING;
                    next_fall_count = 1;
                    next_walk_dir = walk_dir; // preserve original direction
                end
                // Being bumped while digging has no effect
            end

            SPLATTERED: begin
                next_state = SPLATTERED;
                // fall_count and walk_dir don't matter anymore
            end
        endcase
    end

endmodule

