module TopModule (
    input  clk,
    input  reset,
    output ena   [2:0],
    output q     [15:0]
);

    // Internal register to hold the 4-digit BCD counter value
    reg [15:0] counter;

    // Synchronous reset and count logic
    always @(posedge clk) begin
        if (reset) begin
            counter <= 16'd0;
        end else begin
            // BCD counter: roll over from 9999 to 0
            if (counter == 16'd9999) begin
                counter <= 16'd0;
            end else begin
                counter <= counter + 16'd1;
            end
        end
    end

    // Assign the 16-bit output q
    assign q = counter;

    // Generate enable signals for the upper three digits
    // ena[0] enables the tens digit (q[7:4])
    // ena[1] enables the hundreds digit (q[11:8])
    // ena[2] enables the thousands digit (q[15:12])
    assign ena[0] = (counter[3:0] == 4'd9) && (counter[7:4] != 4'd9);
    assign ena[1] = (counter[7:4] == 4'd9) && (counter[11:8] != 4'd9);
    assign ena[2] = (counter[11:8] == 4'd9);

endmodule

Prob150_review2015_fsmonehot.code:
module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  [9:0] state,  // Fixed: 10-bit input as per specification
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

// One-hot state encoding as specified:
// (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
// = (10'b0000000001, 10'b0000000010, 10'b0000000100, 10'b0000001000,
//    10'b0000010000, 10'b0000100000, 10'b0001000000, 10'b0010000000,
//    10'b0100000000, 10'b1000000000)

// State register (combinational next_state generation for the combinational portion)
// Since the specification asks for "only the state transition logic and output logic 
// (the combinational logic portion)", we declare next_state as a wire or reg 
// to hold the computed next state values for this block.
reg [9:0] next_state;

// Combinational next-state logic
always @(*) begin
    // Default: stay in current state to avoid latches if not all cases covered
    // We default to S (10'b0000000001) as per reset state specification.
    next_state = 10'b0000000001; 

    case (state)
        10'b0000000001: begin // S
            if (d == 1'b0)
                next_state = 10'b0000000001; // S
            else
                next_state = 10'b0000000010; // S1
        end
        10'b0000000010: begin // S1
            if (d == 1'b0)
                next_state = 10'b0000000001; // S
            else
                next_state = 10'b0000000100; // S11
        end
        10'b0000000100: begin // S11
            if (d == 1'b0)
                next_state = 10'b0000001000; // S110
            else
                next_state = 10'b0000000100; // S11
        end
        10'b0000001000: begin // S110
            if (d == 1'b0)
                next_state = 10'b0000000001; // S
            else
                next_state = 10'b0000010000; // B0
        end
        10'b0000010000: begin // B0
            // "B0 (shift_ena=1) --(always go to next cycle)--> B1"
            next_state = 10'b0000100000; // B1
        end
        10'b0000100000: begin // B1
            // "B1 (shift_ena=1) --(always go to next cycle)--> B2"
            next_state = 10'b0001000000; // B2
        end
        10'b0001000000: begin // B2
            // "B2 (shift_ena=1) --(always go to next cycle)--> B3"
            next_state = 10'b0010000000; // B3
        end
        10'b0010000000: begin // B3
            // "B3 (shift_ena=1) --(always go to next cycle)--> Count"
            next_state = 10'b0100000000; // Count
        end
        10'b0100000000: begin // Count
            if (done_counting == 1'b0)
                next_state = 10'b0100000000; // Count
            else
                next_state = 10'b1000000000; // Wait
        end
        10'b1000000000: begin // Wait
            if (ack == 1'b1)
                next_state = 10'b0000000001; // S
            else
                next_state = 10'b1000000000; // Wait
        end
        default: next_state = 10'b0000000001; // S
    endcase
end

